      var io = new IntersectionObserver(
        function (es) {
          es.forEach(function (e) {
            if (e.isIntersecting) {
              var t = e.target,
                sib = t.parentElement.querySelectorAll(":scope>.rv");
              t.style.transitionDelay =
                Math.max(0, [].indexOf.call(sib, t)) * 70 + "ms";
              t.classList.add("in");
              io.unobserve(t);
            }
          });
        },
        { threshold: 0.12 },
      );
      document.querySelectorAll(".rv").forEach(function (e) {
        io.observe(e);
      });
      // reveal safety net: anything at or above the viewport bottom is shown (works even if IntersectionObserver misses it)
      function scanRv() {
        var h = innerHeight || document.documentElement.clientHeight;
        document.querySelectorAll(".rv:not(.in)").forEach(function (e) {
          if (e.getBoundingClientRect().top < h * 0.95) e.classList.add("in");
        });
      }
      var _t;
      function qs() {
        cancelAnimationFrame(_t);
        _t = requestAnimationFrame(scanRv);
      }
      addEventListener("scroll", qs, { passive: true });
      addEventListener("resize", qs);
      addEventListener("hashchange", function () {
        setTimeout(scanRv, 60);
        setTimeout(scanRv, 700);
      });
      addEventListener("load", function () {
        scanRv();
        setTimeout(scanRv, 600);
      });
      setTimeout(scanRv, 200);
      var sp = new IntersectionObserver(
        function (es) {
          es.forEach(function (e) {
            if (e.isIntersecting)
              document.querySelectorAll("#nl a").forEach(function (a) {
                a.classList.toggle(
                  "on",
                  a.getAttribute("href") == "#" + e.target.id,
                );
              });
          });
        },
        { rootMargin: "-45% 0px -50% 0px" },
      );
      document.querySelectorAll("section[id]").forEach(function (s) {
        sp.observe(s);
      });
      var fab = document.querySelector(".fab");
